// dydo guard — OpenCode v1 plugin adapter (generated by `dydo init opencode`).
//
// Binds to OpenCode's v1 `tool.execute.before` hook and pipes a Claude-shaped
// HookInput JSON payload to `dydo guard` on stdin. Contract:
//   exit 0 -> allow
//   exit 2 -> throw new Error(stderr)   (blocks the tool call)
//   other  -> allow + log              (deliberate fail-open)
//
// `apply_patch` carries no filePath: its target paths live in `patchText` marker
// lines and `dydo guard` extracts them. `task`, `webfetch`, `websearch` and
// `list` are ignored, as is any tool the guard cannot govern.

import { spawn } from "node:child_process"
import { existsSync } from "node:fs"
import { join } from "node:path"

const IGNORED_TOOLS = new Set(["task", "webfetch", "websearch", "list"])

// OpenCode args -> Claude-shaped `tool_input`. Only these tools reach the guard.
const TOOL_INPUTS = {
  read: (args) => ({ tool_name: "read", tool_input: { file_path: args && args.filePath } }),
  edit: (args) => ({ tool_name: "edit", tool_input: { file_path: args && args.filePath } }),
  write: (args) => ({ tool_name: "write", tool_input: { file_path: args && args.filePath } }),
  bash: (args) => ({ tool_name: "bash", tool_input: { command: args && args.command } }),
  grep: (args) => ({ tool_name: "grep", tool_input: { path: args && args.path } }),
  glob: (args) => ({ tool_name: "glob", tool_input: { path: args && args.path } }),
  apply_patch: (args) => ({ tool_name: "apply_patch", tool_input: { patch_text: args && args.patchText } }),
}

// Locate `dydo` on PATH. Windows installs expose a `.cmd` (npm/pnpm shim), a
// native `.exe`, or a `.ps1`; POSIX exposes an extensionless shim.
function resolveDydo() {
  const isWindows = process.platform === "win32"
  const dirs = (process.env.PATH || "").split(isWindows ? ";" : ":")
  const extensions = isWindows ? [".exe", ".cmd", ".bat", ".ps1", ""] : [""]
  for (const dir of dirs) {
    if (!dir) continue
    for (const extension of extensions) {
      const candidate = join(dir, `dydo${extension}`)
      if (existsSync(candidate)) return candidate
    }
  }
  return null
}

function quoteArg(value) {
  return `"${value}"`
}

// Spawn `dydo guard`, write the payload to stdin, and resolve with the exit code
// and stderr. A spawn failure resolves with a null code so the caller fails open.
function runGuard(resolved, payload, cwd) {
  return new Promise((resolve) => {
    const lower = resolved.toLowerCase()
    const options = { cwd, windowsHide: true }
    let child

    try {
      if (process.platform === "win32" && lower.endsWith(".ps1")) {
        child = spawn(
          process.env.PWSH || "powershell",
          ["-NoProfile", "-ExecutionPolicy", "Bypass", "-File", resolved, "guard"],
          options,
        )
      } else if (process.platform === "win32" && (lower.endsWith(".cmd") || lower.endsWith(".bat"))) {
        child = spawn(`${quoteArg(resolved)} guard`, { ...options, shell: true })
      } else {
        child = spawn(resolved, ["guard"], options)
      }
    } catch (error) {
      resolve({ code: null, stderr: "", error })
      return
    }

    let stderr = ""
    if (child.stderr) child.stderr.on("data", (chunk) => { stderr += chunk.toString() })
    child.on("error", (error) => resolve({ code: null, stderr, error }))
    child.on("close", (code) => resolve({ code, stderr, error: null }))
    if (child.stdin) {
      child.stdin.on("error", () => {})
      child.stdin.end(payload)
    }
  })
}

async function log(client, level, message) {
  try {
    await client?.app?.log?.({ body: { service: "dydo-guard", level, message } })
  } catch {
    // Logging must never affect enforcement.
  }
}

export const DydoGuard = async ({ client, directory, worktree }) => {
  await log(client, "info", "Dydo guard plugin loaded")

  const projectDir = directory || worktree || process.cwd()
  const dydo = resolveDydo()

  return {
    "tool.execute.before": async (input, output) => {
      if (IGNORED_TOOLS.has(input.tool)) return

      const map = TOOL_INPUTS[input.tool]
      if (!map) return

      if (!dydo) {
        await log(client, "warn", `dydo guard not found on PATH; allowing ${input.tool}`)
        return
      }

      const payload = JSON.stringify({
        session_id: input.sessionID || input.sessionId || "opencode",
        cwd: projectDir,
        hook_event_name: "PreToolUse",
        ...map(output.args),
      })

      const { code, stderr } = await runGuard(dydo, payload, projectDir)

      if (code === 0) return
      if (code === 2) {
        throw new Error(stderr.trim() || "Blocked by dydo guard.")
      }

      await log(
        client,
        "warn",
        `dydo guard exited ${code === null ? "unexpectedly" : code}; allowing ${input.tool}${stderr.trim() ? `: ${stderr.trim()}` : ""}`,
      )
    },
  }
}
